import{_ as a,o,c as d,a2 as r}from"./chunks/framework.Ch4PdLd_.js";const p=JSON.parse('{"title":"常见问题与排错","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),t={name:"faq.md"};function c(n,e,l,i,h,s){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="常见问题与排错" tabindex="-1">常见问题与排错 <a class="header-anchor" href="#常见问题与排错" aria-label="Permalink to &quot;常见问题与排错&quot;">​</a></h1><h2 id="安装与更新" tabindex="-1">安装与更新 <a class="header-anchor" href="#安装与更新" aria-label="Permalink to &quot;安装与更新&quot;">​</a></h2><h3 id="安装后提示找不到-nek" tabindex="-1">安装后提示找不到 <code>nek</code> <a class="header-anchor" href="#安装后提示找不到-nek" aria-label="Permalink to &quot;安装后提示找不到 `nek`&quot;">​</a></h3><ul><li><strong>Linux/macOS</strong>：确认 <code>~/.local/bin</code>（或 <code>NEK_BIN_DIR</code>）在 PATH 里。把安装脚本打印的那一行加入 <code>~/.bashrc</code> 或 <code>~/.zshrc</code>，然后重开终端。</li><li><strong>Windows</strong>：安装脚本会把 <code>%LOCALAPPDATA%\\nekcode\\bin</code> 加入用户 PATH，但已经打开的终端不会刷新，请新开一个 PowerShell 窗口。</li></ul><h3 id="安装脚本说没有-nek-v-发布标签" tabindex="-1">安装脚本说没有 <code>nek-v*</code> 发布标签 <a class="header-anchor" href="#安装脚本说没有-nek-v-发布标签" aria-label="Permalink to &quot;安装脚本说没有 `nek-v*` 发布标签&quot;">​</a></h3><p>stable 通道需要至少一个发布标签。还没有发布时，改用 dev 通道：<code>NEK_CHANNEL=dev</code> 再运行安装脚本，见 <a href="/nekcode/start/install#install-options">安装</a>。安装脚本不会悄悄切换通道。</p><h3 id="nek-update-停下来说有本地改动" tabindex="-1"><code>nek update</code> 停下来说有本地改动 <a class="header-anchor" href="#nek-update-停下来说有本地改动" aria-label="Permalink to &quot;`nek update` 停下来说有本地改动&quot;">​</a></h3><p>你修改过安装目录里的源码，或在里面有自己的提交。安装脚本不会覆盖它们。如果改动不需要保留，到安装目录（默认 <code>~/.local/share/nekcode</code> 或 <code>%LOCALAPPDATA%\\nekcode</code>）里自行处理（例如 <code>git status</code> 查看后还原），然后重新运行 <code>nek update</code>。</p><h3 id="更新后行为没有变化" tabindex="-1">更新后行为没有变化 <a class="header-anchor" href="#更新后行为没有变化" aria-label="Permalink to &quot;更新后行为没有变化&quot;">​</a></h3><p>已经打开的 nek 会话仍在运行旧代码，退出后重新运行 <code>nek</code>。</p><h3 id="node-js-版本不够" tabindex="-1">Node.js 版本不够 <a class="header-anchor" href="#node-js-版本不够" aria-label="Permalink to &quot;Node.js 版本不够&quot;">​</a></h3><p>nek 需要 Node.js 22.19 或更高版本。用 <code>node --version</code> 检查，升级后重新运行安装脚本。</p><h3 id="启动时出现-experimentalwarning-sqlite-is-an-experimental-feature" tabindex="-1">启动时出现 <code>ExperimentalWarning: SQLite is an experimental feature</code> <a class="header-anchor" href="#启动时出现-experimentalwarning-sqlite-is-an-experimental-feature" aria-label="Permalink to &quot;启动时出现 `ExperimentalWarning: SQLite is an experimental feature`&quot;">​</a></h3><p>这是 Node.js 对内置 <code>node:sqlite</code> 模块的提示，不影响使用。</p><h2 id="模型与登录" tabindex="-1">模型与登录 <a class="header-anchor" href="#模型与登录" aria-label="Permalink to &quot;模型与登录&quot;">​</a></h2><h3 id="model-里看不到想要的模型" tabindex="-1"><code>/model</code> 里看不到想要的模型 <a class="header-anchor" href="#model-里看不到想要的模型" aria-label="Permalink to &quot;`/model` 里看不到想要的模型&quot;">​</a></h3><ul><li>确认该服务商有可用的凭据（<code>/login</code> 或环境变量）；</li><li><code>models.json</code> 里的模型也需要能解析到凭据才会出现；</li><li>用 <code>nek --list-models &lt;关键词&gt;</code> 在命令行检查；</li><li>llama.cpp 只显示路由服务当前加载的模型。</li></ul><p>见 <a href="/nekcode/guide/models">选择模型</a>。</p><h3 id="中转接口报错或输出异常" tabindex="-1">中转接口报错或输出异常 <a class="header-anchor" href="#中转接口报错或输出异常" aria-label="Permalink to &quot;中转接口报错或输出异常&quot;">​</a></h3><p>检查 <code>models.json</code> 里的 <code>api</code> 是否与接口的真实协议一致（<code>openai-completions</code>、<code>openai-responses</code>、<code>anthropic-messages</code> 等），以及 <code>baseUrl</code> 是否包含正确的路径（例如是否需要 <code>/v1</code>）。思考等级不被接受时，用 <code>thinkingLevelMap</code> 映射或禁用不支持的等级。</p><h3 id="请求经常中断或很慢才报错" tabindex="-1">请求经常中断或很慢才报错 <a class="header-anchor" href="#请求经常中断或很慢才报错" aria-label="Permalink to &quot;请求经常中断或很慢才报错&quot;">​</a></h3><ul><li>临时错误（过载、限流、5xx、流在完成前断开）会按 <code>retry</code> 设置自动重试；</li><li>上游卡住但没有断开连接时，nek 要等 <code>httpIdleTimeoutMs</code>（默认 5 分钟）才报错重试。确认上游在长时间推理时也会持续发送数据后，可以考虑调小这个值；</li><li>需要代理时设置 <code>httpProxy</code>（只能在用户级设置）或 <code>HTTPS_PROXY</code>。</li></ul><h3 id="在远程服务器上无法完成-oauth-登录" tabindex="-1">在远程服务器上无法完成 OAuth 登录 <a class="header-anchor" href="#在远程服务器上无法完成-oauth-登录" aria-label="Permalink to &quot;在远程服务器上无法完成 OAuth 登录&quot;">​</a></h3><p>出现提示时，把浏览器最终跳转到的完整地址（或授权码）粘贴回 nek。也可以改用 API key。</p><h2 id="界面与按键" tabindex="-1">界面与按键 <a class="header-anchor" href="#界面与按键" aria-label="Permalink to &quot;界面与按键&quot;">​</a></h2><h3 id="shift-enter-直接发送了消息" tabindex="-1"><code>Shift+Enter</code> 直接发送了消息 <a class="header-anchor" href="#shift-enter-直接发送了消息" aria-label="Permalink to &quot;`Shift+Enter` 直接发送了消息&quot;">​</a></h3><p>终端没有把修饰键传给 nek。临时可以用 <code>Ctrl+J</code> 换行；根本解决见 <a href="/nekcode/platform/terminal-setup">终端设置</a>，tmux 见 <a href="/nekcode/platform/tmux">在 tmux 中运行</a>。</p><h3 id="在-tmux-里鼠标滚轮不能滚动对话" tabindex="-1">在 tmux 里鼠标滚轮不能滚动对话 <a class="header-anchor" href="#在-tmux-里鼠标滚轮不能滚动对话" aria-label="Permalink to &quot;在 tmux 里鼠标滚轮不能滚动对话&quot;">​</a></h3><p>在 <code>~/.tmux.conf</code> 中加入 <code>set -g mouse on</code> 并重载配置。键盘的 <code>PageUp</code>/<code>PageDown</code> 始终可用。或者改用普通模式 <code>nek --tui-mode regular</code>。</p><h3 id="想用终端自己的滚动条和搜索" tabindex="-1">想用终端自己的滚动条和搜索 <a class="header-anchor" href="#想用终端自己的滚动条和搜索" aria-label="Permalink to &quot;想用终端自己的滚动条和搜索&quot;">​</a></h3><p>使用普通模式：<code>nek --tui-mode regular</code>，或在 <code>/settings</code> 里把 TUI mode 改成 regular。</p><h3 id="中文输入法的候选框位置不对" tabindex="-1">中文输入法的候选框位置不对 <a class="header-anchor" href="#中文输入法的候选框位置不对" aria-label="Permalink to &quot;中文输入法的候选框位置不对&quot;">​</a></h3><p>设置 <code>NEK_HARDWARE_CURSOR=1</code> 或在设置里打开 <code>showHardwareCursor</code>。</p><h3 id="windows-上-alt-enter-不能排队消息" tabindex="-1">Windows 上 <code>Alt+Enter</code> 不能排队消息 <a class="header-anchor" href="#windows-上-alt-enter-不能排队消息" aria-label="Permalink to &quot;Windows 上 `Alt+Enter` 不能排队消息&quot;">​</a></h3><p>Windows Terminal 占用了 <code>Alt+Enter</code>，nek 在 Windows/WSL 上用 <code>Ctrl+Q</code> 排队追加消息，见 <a href="/nekcode/platform/windows">在 Windows 上运行</a>。</p><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><h3 id="ast-grep-或大文件的代码大纲不可用" tabindex="-1"><code>ast_grep</code> 或大文件的代码大纲不可用 <a class="header-anchor" href="#ast-grep-或大文件的代码大纲不可用" aria-label="Permalink to &quot;`ast_grep` 或大文件的代码大纲不可用&quot;">​</a></h3><p>nek 找不到可用的 ast-grep。检查 <code>~/.nek/agent/bin/</code> 或 PATH 中是否有 <code>ast-grep</code>。Linux 上自动下载的版本需要 <code>unzip</code> 和 glibc 2.34+，老系统或 Alpine 请用 <code>npm install -g @ast-grep/cli</code> 自行安装。见 <a href="/nekcode/start/install#search-tools">搜索工具</a>。</p><h3 id="模型说-write-失败-要求先读文件" tabindex="-1">模型说 <code>write</code> 失败，要求先读文件 <a class="header-anchor" href="#模型说-write-失败-要求先读文件" aria-label="Permalink to &quot;模型说 `write` 失败，要求先读文件&quot;">​</a></h3><p>覆盖已有文件前必须先读过它。这是有意的保护：防止基于过期内容整份覆盖。模型读一次文件后就可以写；局部修改应使用 <code>edit</code>，它不要求先读。</p><h3 id="plan-模式下模型说只能改-markdown" tabindex="-1">Plan 模式下模型说只能改 Markdown <a class="header-anchor" href="#plan-模式下模型说只能改-markdown" aria-label="Permalink to &quot;Plan 模式下模型说只能改 Markdown&quot;">​</a></h3><p>这是 Plan 模式的限制。审阅计划后选择 Implement，或按 <code>Alt+M</code> / 输入 <code>/agent</code> 回到 Agent 模式。</p><h3 id="别名在-命令或-bash-工具里不能用" tabindex="-1">别名在 <code>!</code> 命令或 <code>bash</code> 工具里不能用 <a class="header-anchor" href="#别名在-命令或-bash-工具里不能用" aria-label="Permalink to &quot;别名在 `!` 命令或 `bash` 工具里不能用&quot;">​</a></h3><p>nek 用非交互的 Bash 执行命令，默认不展开别名。用 <code>shellCommandPrefix</code> 加载别名文件，见 <a href="/nekcode/platform/shell">Shell 命令配置</a>。</p><h3 id="模型老是问问题-打断工作" tabindex="-1">模型老是问问题，打断工作 <a class="header-anchor" href="#模型老是问问题-打断工作" aria-label="Permalink to &quot;模型老是问问题，打断工作&quot;">​</a></h3><p>nek 的提示词已要求模型只在真正需要你决定时才提问。如果仍然觉得打扰，可以在 <code>AGENTS.md</code> 中写明你的偏好，或用 <code>--exclude-tools ask_question</code> 禁用提问工具。</p><h2 id="子代理" tabindex="-1">子代理 <a class="header-anchor" href="#子代理" aria-label="Permalink to &quot;子代理&quot;">​</a></h2><h3 id="为什么-agents-默认只有-explorer" tabindex="-1">为什么 <code>/agents</code> 默认只有 <code>explorer</code>？ <a class="header-anchor" href="#为什么-agents-默认只有-explorer" aria-label="Permalink to &quot;为什么 `/agents` 默认只有 `explorer`？&quot;">​</a></h3><p>公共版本只内置只读 <code>explorer</code>，默认继承父会话的模型和思考等级，不附带个人子代理配置。其他类型需自行定义，见 <a href="/nekcode/guide/subagents#custom-types">自定义类型</a>。如果列表里还有其他类型，检查本机 <code>~/.nek/agent/agents/</code> 和项目 <code>.nek/agents/</code> 中的文件。</p><h3 id="提示-subagent-limit-reached" tabindex="-1">提示 <code>Subagent limit reached</code> <a class="header-anchor" href="#提示-subagent-limit-reached" aria-label="Permalink to &quot;提示 `Subagent limit reached`&quot;">​</a></h3><p>同时运行的子代理达到上限（默认 6）。等一个完成，或用 <code>/subagents</code> 取消一个；也可以在 <code>nek.yaml</code> 中调整 <code>subagent.maxConcurrent</code>。</p><h3 id="子代理里没有-mcp-工具" tabindex="-1">子代理里没有 MCP 工具 <a class="header-anchor" href="#子代理里没有-mcp-工具" aria-label="Permalink to &quot;子代理里没有 MCP 工具&quot;">​</a></h3><p>子代理不加载 MCP，这是有意的设计。需要 MCP 的工作请在父会话中完成。</p><h2 id="会话" tabindex="-1">会话 <a class="header-anchor" href="#会话" aria-label="Permalink to &quot;会话&quot;">​</a></h2><h3 id="nek-被强制结束后-之前的工作还在吗" tabindex="-1">nek 被强制结束后，之前的工作还在吗？ <a class="header-anchor" href="#nek-被强制结束后-之前的工作还在吗" aria-label="Permalink to &quot;nek 被强制结束后，之前的工作还在吗？&quot;">​</a></h3><p>在。用 <code>nek -c</code>（或 <code>/resume</code>）重新打开会话，中断的那一轮会继续。会修改外部状态的工具（<code>bash</code>、<code>edit</code>、<code>write</code> 等）不会被自动重跑，模型会看到“已中断”的结果并决定下一步。见 <a href="/nekcode/reference/durable-sessions">Durable 会话</a>。</p><h3 id="提示会话已被其他进程打开" tabindex="-1">提示会话已被其他进程打开 <a class="header-anchor" href="#提示会话已被其他进程打开" aria-label="Permalink to &quot;提示会话已被其他进程打开&quot;">​</a></h3><p>同一个会话不能被两个 nek 进程同时打开（有 <code>.lock</code> 文件）。关闭另一个进程，或用 <code>/new</code> 开新会话。</p><h3 id="上下文很快就满了" tabindex="-1">上下文很快就满了 <a class="header-anchor" href="#上下文很快就满了" aria-label="Permalink to &quot;上下文很快就满了&quot;">​</a></h3><ul><li>状态栏的进度条显示当前用量；</li><li><code>/compact</code> 手动压缩，可以附加说明保留重点；</li><li>长任务可以在 Plan 模式审阅时选 <strong>Fresh context</strong> 在新会话里实施；</li><li>大范围的代码探索交给 <code>explorer</code> 子代理，避免搜索输出塞满主会话；</li><li>用 <code>compaction.model</code> 指定一个上下文更长或更便宜的模型写摘要。</li></ul><h2 id="获取帮助" tabindex="-1">获取帮助 <a class="header-anchor" href="#获取帮助" aria-label="Permalink to &quot;获取帮助&quot;">​</a></h2><ul><li>运行 <code>/debug</code> 收集诊断信息（分享前检查内容）；</li><li>在 <a href="https://github.com/deepdarkpaw/nekcode/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 报告问题，附上 <code>nek --version</code> 的输出、操作系统和终端；</li><li>安全问题请按 <a href="https://github.com/deepdarkpaw/nekcode/blob/nek/SECURITY.md" target="_blank" rel="noreferrer">安全策略</a> 私下报告。</li></ul>',62)])])}const m=a(t,[["render",c]]);export{p as __pageData,m as default};
